# Recorded v16 source. Original prompt strings are preserved with Unicode escapes.
"""Render recorded model outputs; never author or relabel scientific graph content."""
import argparse
import json
from pathlib import Path
import semantic_stitch as s
ROOT = Path(__file__).resolve().parent

def encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')

def payload(out):
    graph = s.read(out / 'inputs/knowledge_graph.json')
    index = s.read(out / 'semantic_index.json')
    classification = graph['classification']
    ranking = s.read(out / 'column_ranking.json')
    context = s.read(out / 'research_context.json')
    retrieval = s.read(out / 'semantic_retrieval.json')
    workflow = s.read(out / 'stitched_workflow.json')
    dataset = next((d for d in s.read(out / 'data_features.json')['datasets'] if d['dataset_id'] == context['dataset_choice']['dataset_id']))
    cref_by_m = {m['method_id']: m['component_refs'] for m in index['methods']}
    nodes = [{'id': f['id'], 'kind': 'family', 'label': f['id'] + ' ' + f['name'], 'component_refs': [ref for m in index['methods'] if m['family_id'] == f['id'] for ref in m['component_refs']]} for f in classification['families']]
    nodes += [{'id': m['id'], 'kind': 'method', 'label': m['id'] + ' ' + m['name'], 'component_refs': cref_by_m[m['id']]} for m in classification['methods']]
    nodes += [{'id': ref, 'kind': 'option', 'label': ref + ' ' + o['option']['label'], 'component_refs': [ref + '/' + c['id'] for r in classification['rows'] if r['source_ref'] == ref for c in r['components']]} for ref, o in graph['original_options'].items()]
    edges = [{'from': m['family_id'], 'to': m['id'], 'kind': 'family_membership', 'origin': 'frozen_graph', 'reason': '\u539f\u6709\u5bb6\u65cf\u5f52\u5c5e'} for m in classification['methods']]
    seen = set()
    for row in classification['rows']:
        for comp in row['components']:
            key = (comp['method_id'], row['source_ref'])
            if key in seen:
                continue
            seen.add(key)
            edges.append({'from': key[0], 'to': key[1], 'kind': 'instance_mapping', 'origin': 'frozen_graph', 'reason': '\u539f\u6709\u65b9\u6cd5\u5b9e\u4f8b\u6620\u5c04'})
    selected_refs = {ref for q in retrieval['queries'] for c in q['candidates'] for ref in c['support_component_refs']}
    details = {ref: {**index['components'][ref], 'columns': [{k: c[k] for k in ['name', 'role', 'meaning', 'h1_relation']} for c in index['components'][ref]['columns']]} for ref in sorted(selected_refs)}
    return {'paper': s.read(out / 'selection.json')['paper'], 'context': context, 'dataset': {k: dataset[k] for k in ['dataset_id', 'rows', 'column_count', 'table', 'file']}, 'ranking': ranking, 'retrieval': retrieval, 'workflow': workflow, 'method_index': index['methods'], 'stages': s.STAGES, 'graph': {'nodes': nodes, 'edges': edges}, 'selected_component_details': details}

def build(out):
    data = payload(out)
    template = (ROOT / 'semantic_stitch_fragment.html').read_text(encoding='utf-8')
    fragment = template.replace('__DATA__', encode(data))
    if len(fragment.encode()) >= 1000000:
        raise ValueError('Inline fragment exceeds 1MB; use lossless references before publication')
    if '<!doctype' in fragment.lower():
        raise ValueError('Inline fragment must not contain a document wrapper')
    (out / 'retrieval-stitch.html').write_text(fragment, encoding='utf-8')
    components = s.read(out / 'semantic_index.json')['components']
    shell = (ROOT / 'semantic_stitch_shell.html').read_text(encoding='utf-8')
    (out / 'index.html').write_text(shell.replace('__COMPONENTS__', encode(components)).replace('__FRAGMENT__', fragment), encoding='utf-8')
    s.save(out / '\u5c55\u793a\u6570\u636e.json', data)
    write_readme(out, data)
    print('View built: ' + str(len(fragment.encode())) + ' inline bytes; full graph ' + str(len(data['graph']['nodes'])) + ' nodes', flush=True)

def write_technical_readme(out, d):
    verify = s.read(out / 'verification.json')
    ranking = sorted(d['ranking']['columns'], key=lambda c: c['rank'])
    rows = '\n'.join(('| ' + str(c['rank']) + ' | ' + c['name'].replace('|', '/') + ' | ' + c['role'].replace('|', '/') + ' | ' + c['importance_reason'].replace('|', '/') + ' |' for c in ranking[:5]))
    text = f'# \u6570\u636e\u5217\u8bed\u4e49\u68c0\u7d22\u4e0e\u73b0\u6709\u65b9\u6cd5\u56fe\u62fc\u63a5\u8bd5\u9519\n\n\u672c\u8f6e\u505c\u5728\u62fc\u63a5\u5b8c\u6210：**\u6ca1\u6709\u751f\u6210 Boba \u6a21\u677f，\u6ca1\u6709\u8fd0\u884c\u7edf\u8ba1\u5206\u6790，\u6ca1\u6709\u4f30\u8ba1\u503c、P\u503c\u6216 Specification Curve。**\n\n## \u672c\u8f6e\u8f93\u5165\u4e0e\u7ed3\u679c\n\n- \u4e8c\u5341\u7bc7\u4e4b\u5916\u7684\u8bba\u6587：{d['paper']['title']}。\n- \u4ece\u5e93\u4e2d\u672a\u4f7f\u7528、\u540c\u65f6\u9644\u53ef\u8bc6\u522b\u4ee3\u7801\u548c\u6570\u636e\u6587\u4ef6\u7684\u5019\u9009\u673a\u68b0\u9009\u62e9；\u672c\u8f6e\u6709{s.read(out / 'selection.json')['candidate_count']}\u4e2a\u5019\u9009，\u6309\u8bb0\u5f55\u7684\u673a\u68b0\u987a\u5e8f\u9009\u53d6。\u4e0d\u662f\u5f00\u53d1\u8005\u6309\u8bba\u6587\u5185\u5bb9\u6311\u9009。\n- \u6570\u636e\u7531\u666e\u901a\u7a0b\u5e8f\u8bfb\u53d6，\u5f97\u5230{len(s.read(out / 'data_features.json')['datasets'])}\u5f20\u8868；DeepSeek\u9009\u62e9 {d['dataset']['dataset_id']}，{d['dataset']['rows']}\u884c、{d['dataset']['column_count']}\u5217。\u6587\u4ef6\u80fd\u8bfb\u4e0d\u7b49\u4e8e\u539f\u59cb\u5fae\u89c2\u89c2\u6d4b\u5df2\u5b8c\u6574\u53ef\u7528。\n- H1：{d['context']['h1']['text']}\n- \u4e0e\u8bba\u6587\u603b\u4e3b\u5f20\u7684\u533a\u522b：{d['context']['difference_from_original']}\n- \u524d{verify['queries']}\u5217\u8bed\u4e49\u7528\u4e8e\u68c0\u7d22，\u547d\u4e2d{verify['unique_retrieved_methods']}\u4e2a\u4e0d\u540cM，\u62fc\u63a5\u4e3a{verify['application_nodes']}\u4e2a\u5e94\u7528\u8282\u70b9、{verify['proposed_workflow_edges']}\u6761\u5019\u9009\u8fde\u63a5。\n- \u5f53\u524d\u6709 {sum((n['status'] == 'blocked' for n in d['workflow']['nodes']))} \u4e2a\u8282\u70b9\u6807\u4e3ablocked；{sum((g['status'] == 'gap' for g in d['workflow']['stage_checks']))} \u4e2a\u9636\u6bb5\u7559\u6709\u7f3a\u53e3。\u56fe\u5df2\u7ecf\u62fc\u63a5，\u5c1a\u4e0d\u662f\u53ef\u6267\u884c\u5206\u6790\u6d41\u7a0b；\u8fd9\u4e9b\u6807\u8bb0\u6765\u81eaDeepSeek，\u4e0d\u7531\u5f00\u53d1\u8005\u6539\u6210\u901a\u8fc7。\n\n## \u9875\u9762\u770b\u4ec0\u4e48\n\n\u53cc\u51fb index.html（\u53ef\u79bb\u7ebf）。\u9875\u9762\u5206\u4e09\u90e8\u5206：\n1. \u6570\u636e\u5217\u6392\u5e8f：\u524d{verify['queries']}\u5217\u5148\u5c55\u793a，\u53ef\u5c55\u5f00\u5168\u90e8{len(ranking)}\u5217；\u542b\u5217\u8bed\u4e49、H1\u89d2\u8272、\u6392\u5e8f\u7406\u7531\u548c\u6765\u6e90\u5f15\u6587。\u524d{verify['queries']}\u5217\u53ef\u70b9“\u67e5\u770b\u5339\u914d”。\u6392\u5e8f\u662f\u6a21\u578b\u7684\u7814\u7a76\u5173\u8054\u5224\u65ad，\u4e0d\u662f\u9884\u6d4b\u8d21\u732e、\u663e\u8457\u6027\u6216\u5df2\u6d4b\u91cf\u7684\u56e0\u679c\u91cd\u8981\u6027。\n2. \u73b0\u6709\u56fe\u4e0e\u547d\u4e2d\u8282\u70b9：\u663e\u793a\u771f\u6b63\u51bb\u7ed3\u768420\u7bc7 F→M→Option \u56fe，\u53ef\u5207\u6362\u67e5\u8be2\u5217、\u65b9\u6cd5\u5bb6\u65cf\u6216\u5b8c\u6574\u56fe。\u539f\u8fde\u7ebf\u4e3a\u65b9\u6cd5\u5f52\u5c5e/\u5b9e\u4f8b\u6620\u5c04，\u547d\u4e2d\u8282\u70b9\u5355\u72ec\u7a81\u51fa；\u76f8\u5173\u6027\u5206\u6570\u662f\u6a21\u578b\u5224\u65ad，\u9002\u7528\u6027\u53e6\u5217。\u5b8c\u6574\u56fe{len(d['graph']['nodes'])}\u8282\u70b9，\u539f\u6709\u6620\u5c04\u8fde\u7ebf{len(d['graph']['edges'])}\u6761。\n3. \u62fc\u63a5\u6d41\u7a0b：\u901a\u7528\u9aa8\u67b6\u662f“\u6837\u672c\u4e0e\u5217\u51c6\u5907→\u7f3a\u5931\u503c\u5904\u7406→\u53d8\u91cf\u6784\u9020→\u6a21\u578b\u4f30\u8ba1→\u63a8\u65ad\u4e0e\u8bca\u65ad”。\u9aa8\u67b6\u7531\u5f00\u53d1\u8005\u9884\u8bbe，\u4ec5\u7528\u4e8e\u7ec4\u7ec7；\u5177\u4f53\u65b9\u6cd5、\u5217\u7ed1\u5b9a、\u6761\u4ef6\u548c\u7f3a\u53e3\u7531DeepSeek\u5224\u65ad。\u65b0\u8fde\u7ebf\u5747\u6807\u8bb0proposed_stitch，\u4e0d\u80fd\u5192\u5145\u8bba\u6587\u5df2\u62a5\u544a\u7684\u8de8\u8bba\u6587\u6267\u884c\u6d41\u7a0b。\u5907\u9009\u5173\u7cfb\u4e0d\u5f53\u6210\u5fc5\u987b\u5148\u540e\u6267\u884c\u7684\u6570\u636e\u6d41。\n\n| H1\u5173\u8054\u6392\u5e8f | \u5b9e\u9645\u5217\u540d | \u7814\u7a76\u89d2\u8272 | \u6392\u5e8f\u7406\u7531 |\n| --- | --- | --- | --- |\n{rows}\n\n## “\u6bcf\u4e2a\u8282\u70b9\u7684\u6570\u636e\u5217\u8bed\u4e49”\u5982\u4f55\u8bb0\u5f55\n\n\u4fdd\u7559\u539f\u56fe\u4e0d\u53d8，\u53e6\u5efasemantic_index.json：\u7ec4\u4ef6\u4fdd\u5b58\u539f\u6709\u5b9e\u9645\u5217\u540d、\u89d2\u8272、\u8bed\u4e49\u548c\u539fH1\u5173\u7cfb；\u65b9\u6cd5M\u901a\u8fc7\u5176\u7ec4\u4ef6\u7ee7\u627f\u5e76\u6c47\u603b；\u5bb6\u65cfF\u901a\u8fc7\u5b50\u65b9\u6cd5\u7ee7\u627f；Option\u901a\u8fc7\u539f\u7ec4\u4ef6\u5f15\u7528。\u6c47\u603b\u4ec5\u505a\u53bb\u91cd\u548c\u5f15\u7528，\u4e0d\u7531\u5f00\u53d1\u8005\u91cd\u65b0\u89e3\u91ca。\u6ca1\u6709\u8bed\u4e49\u7684\u8282\u70b9\u660e\u786e\u8bb0\u7f3a\u5931，\u4e0d\u8865\u9020。\n\n\u6d4f\u89c8\u5668\u5b8c\u6574\u7248\u5d4c\u5165\u6240\u6709\u539f\u7ec4\u4ef6\u8bb0\u5f55；\u5bf9\u8bdd\u5185\u7248\u4fdd\u7559\u6240\u6709M\u7684\u6c47\u603b\u8bed\u4e49、\u5168\u56fe\u7ed3\u6784\u548c\u672c\u8f6e\u547d\u4e2d\u7684\u5b9e\u4f8b\u7ec6\u8282。\u4e0d\u80fd\u628a\u65b9\u6cd5\u5c42\u6c47\u603b\u5f53\u6210\u67d0\u4e2aOption\u72ec\u6709\u7684\u5217\u5b9a\u4e49，\u4e5f\u4e0d\u80fd\u628a\u539f\u8bba\u6587\u5217\u81ea\u52a8\u5f53\u4f5c\u76ee\u6807\u6570\u636e\u5217。\n\n## \u5df2\u505a\u7684\u68c0\u67e5\u4e0e\u9650\u5236\n\n\u539f20\u7bc7\u6587\u4ef6SHA\u4e0d\u53d8；\u76ee\u6807\u8bba\u6587\u4e0d\u5c5e\u4e8e20\u7bc7；\u6240\u6709{len(ranking)}\u5217\u4e00\u5217\u4e00\u6b21\u4e14\u6392\u5e8f1—{len(ranking)}；\u6a21\u578b\u5f15\u6587\u53ef\u5728\u8f93\u5165\u6587\u5b57\u627e\u5230；\u68c0\u7d22M、\u5386\u53f2\u7ec4\u4ef6\u5f15\u7528\u53ca\u5176\u5f52\u5c5e\u771f\u5b9e\u5b58\u5728；\u62fc\u63a5\u53ea\u5f15\u7528\u5df2\u68c0\u7d22\u4e14\u672a\u5224\u4e0d\u9002\u7528\u7684\u65e2\u5b58M；\u5217\u7ed1\u5b9a\u53ea\u5141\u8bb8\u771f\u5b9e\u5217ID；\u65b0\u8fb9\u6709\u6765\u6e90\u6807\u7b7e\u548c\u7c7b\u578b；\u6bcf\u4e2a\u901a\u7528\u9636\u6bb5\u4ea4\u4ee3\u8986\u76d6/\u7f3a\u53e3/\u4e0d\u9002\u7528。\n\n\u7ed3\u6784\u68c0\u67e5\u4e0d\u8bc1\u660e\u8bed\u4e49\u6b63\u786e、\u7edf\u8ba1\u9002\u7528\u6216\u53c2\u6570\u53ef\u8fc1\u79fb。\u539f\u5b9e\u4f8b\u53c2\u6570\u4e0d\u80fd\u76f4\u63a5\u4f5c\u4e3a\u65b0\u6570\u636e\u53c2\u6570；\u672a\u77e5\u6761\u4ef6\u4fdd\u7559。\u77e5\u8bc6/\u8349\u56fe\u5c42\u5141\u8bb8\u53cd\u9988\u73af，\u672c\u8f6e\u4e0d\u9a8c\u8bc1\u53ef\u6267\u884c\u62d3\u6251。\u539f20\u7bc7\u5df2\u6709\u5206\u7c7b\u7c92\u5ea6\u95ee\u9898\u5e76\u672a\u5728\u672c\u8f6e\u4fee\u6b63。\n\n## \u72ec\u7acb\u8fd0\u884c\n\n```powershell\n.\\run.ps1 -Replay\n```\n\n\u6216\u5728\u9879\u76ee\u6839\u76ee\u5f55：\n\n```shell\npython outputs/decision_option_lab/semantic_stitch.py --replay\n```\n\n\u666e\u901a\u8fd0\u884c\u4ece\u5df2\u901a\u8fc7\u7f13\u5b58\u7ee7\u7eed；--replay\u4e25\u683c\u79bb\u7ebf，\u7f3a\u7f13\u5b58\u5c31\u62a5\u9519，\u4e0d\u8c03\u7528API。\u65b0\u8c03\u7528\u9700\u8981\u672c\u5730\u6700\u65b0key\u548c\u539f\u59cb\u5206\u4eabZIP；\u8bb0\u5f55\u4e0e\u7f13\u5b58\u91cd\u653e\u624d\u4fdd\u8bc1\u7ed3\u679c\u4e00\u81f4，\u91cd\u65b0\u8bf7\u6c42\u6a21\u578b\u4e0d\u4fdd\u8bc1\u9010\u5b57\u76f8\u540c。\n\n\u672c\u8f6e\u65b0\u589e\u72ec\u7acbsemantic_stitch.py、semantic_stitch_view.py、\u4e09\u6b65\u5c55\u793a\u6a21\u677f、\u56db\u4efd\u6a21\u578b\u4efb\u52a1\u6307\u4ee4\u548c\u72ec\u7acb\u8f93\u51fa\u5951\u7ea6；\u672a\u6539\u65e7\u63d0\u53d6/\u5408\u5e76\u7a0b\u5e8f、\u5206\u7c7b\u89c4\u8303\u621620\u7bc7\u79d1\u5b66\u7ed3\u679c。PDF\u5927\u56fe\u5f62\u5185\u5bb9\u6539\u7528PyMuPDF\u8bfb\u53d6，RData\u7528pyreadr\u76f4\u63a5\u8bfb\u53d6；\u6ca1\u6709\u8fd0\u884c\u4f5c\u8005R\u4ee3\u7801。\u7a0b\u5e8f\u672c\u8eab\u6ca1\u6709\u624b\u5de5\u8bba\u6587\u7b54\u6848。\n'
    (out / '\u6280\u672f\u4e0e\u590d\u73b0\u8bf4\u660e.md').write_text(text, encoding='utf-8')

def write_readme(out, d):
    """Discussion summary from recorded results; scientific problem descriptions are model quotations."""
    write_technical_readme(out, d)
    checks = s.read(out / 'verification.json')
    workflow = d['workflow']
    conditional = sum((n['status'] == 'conditional' for n in workflow['nodes']))
    blocked = [n for n in workflow['nodes'] if n['status'] == 'blocked']
    gaps = [g for g in workflow['stage_checks'] if g['status'] == 'gap']
    gap_text = '\n'.join(('- **\u6d41\u7a0b\u7f3a\u53e3（\u6a21\u578b\u8bf4\u660e）：** ' + g['reason'] for g in gaps))
    block_text = '\n'.join(('- **\u53d7\u963b\u65b9\u6cd5（\u6a21\u578b\u8bf4\u660e，' + n['method_id'] + '）：** ' + n['reason'] for n in blocked))
    inference_notes = list(dict.fromkeys((note for n in workflow['nodes'] if n['stage'] == 'inference' for note in n['unresolved_conditions'] if 'P\u503c' in note or 'P \u503c' in note)))
    inference_text = '\n'.join(('- **\u63a8\u65ad\u9650\u5236（\u6a21\u578b\u8bf4\u660e）：** ' + note for note in inference_notes))
    short_title = d['paper']['title'].split(':', 1)[0]
    text = f'# \u672c\u8f6e\u8bd5\u9519\u7b80\u62a5：\u505a\u4e86\u4ec0\u4e48、\u7ed3\u679c\u4e0e\u95ee\u9898\n\n## 1. \u505a\u4e86\u4ec0\u4e48\n\n\u9009\u53d6\u4e8c\u5341\u7bc7\u4e4b\u5916\u7684 **{short_title}**。DeepSeek \u4ece\u8bba\u6587\u5df2\u62a5\u544a\u7684\u5b9e\u8bc1\u5b50\u4e3b\u5f20\u4e2d\u786e\u5b9aH1：\n\n> {d['context']['h1']['text']}\n\n\u666e\u901a\u7a0b\u5e8f\u6d4b\u91cf\u5217\u7279\u5f81；DeepSeek\u5b8c\u6210“**\u5217\u8bed\u4e49\u4e0eH1\u91cd\u8981\u6027\u6392\u5e8f→\u524d{checks['queries']}\u5217\u68c0\u7d22\u539f\u56fe→\u6309\u5b9e\u8bc1\u5206\u6790\u9636\u6bb5\u62fc\u63a5\u6d41\u7a0b**”。\u79d1\u7814\u5224\u65ad\u7531DeepSeek\u5b8c\u6210，\u5f00\u53d1\u8005\u4e0d\u624b\u6539\u8bba\u6587\u7b54\u6848\u6216\u65b9\u6cd5\u6620\u5c04。\n\n## 2. \u7ed3\u679c\u600e\u4e48\u6837\n\n- \u76ee\u6807\u8868 **{d['dataset']['rows']}\u884c、{d['dataset']['column_count']}\u5217**；\u68c0\u7d22\u5230 **{checks['unique_retrieved_methods']}\u4e2aMethod**，\u62fc\u63a5 **{checks['application_nodes']}\u4e2a\u5e94\u7528\u8282\u70b9、{checks['proposed_workflow_edges']}\u6761\u5efa\u8bae\u8fde\u63a5**。\n- **\u4fe1\u606f\u5904\u7406\u6d41\u7a0b\u8dd1\u901a，\u4f46\u5206\u6790\u6d41\u7a0b\u5c1a\u4e0d\u53ef\u6267\u884c**：{conditional}\u4e2a\u8282\u70b9\u6709\u5f85\u786e\u8ba4\u7684\u6761\u4ef6，{len(blocked)}\u4e2a\u53d7\u963b\u8282\u70b9，{len(gaps)}\u4e2a\u9636\u6bb5\u7f3a\u53e3。\n- \u539f\u4e8c\u5341\u7bc7\u56fe\u672a\u53d8，\u79bb\u7ebf\u91cd\u653e\u548c\u7ed3\u6784\u68c0\u67e5\u901a\u8fc7。\u672a\u751f\u6210Boba\u6a21\u677f、\u8fd0\u884c\u5206\u6790\u6216\u8f93\u51fa\u66f2\u7ebf，\u5c1a\u4e0d\u80fd\u5224\u65adH1\u662f\u5426\u6210\u7acb。\n\n## 3. \u76ee\u524d\u6709\u4ec0\u4e48\u95ee\u9898\n\n\u4ee5\u4e0b\u5177\u4f53\u95ee\u9898\u6765\u81eaDeepSeek\u7684\u8f93\u51fa，\u672a\u7531\u5f00\u53d1\u8005\u91cd\u65b0\u88c1\u5b9a：\n\n{gap_text}\n{block_text}\n{inference_text}\n- **\u5171\u540c\u9650\u5236：** \u8bed\u4e49\u76f8\u8fd1\u4e0d\u7b49\u4e8e\u65b9\u6cd5、\u6743\u91cd\u548c\u53c2\u6570\u53ef\u8fc1\u79fb；\u6392\u5e8f\u548c\u5339\u914d\u6ca1\u6709\u72ec\u7acb\u51c6\u786e\u7387\u9a8c\u8bc1。\u7ed3\u6784\u68c0\u67e5\u4e0d\u8bc1\u660e\u7edf\u8ba1\u6709\u6548，\u539f\u56fe\u5206\u7c7b\u7c92\u5ea6\u95ee\u9898\u4e5f\u672a\u89e3\u51b3。\n\n## 4. \u5efa\u8bae\u4e0e\u79d1\u7814\u52a9\u624b\u8ba8\u8bba\n\n**\u662f\u5426\u540c\u65f6\u6309“H1\u6240\u9700\u7684\u64cd\u4f5c”\u68c0\u7d22，\u800c\u4e0d\u53ea\u6309\u5217\u8bed\u4e49\u68c0\u7d22？** \u5f53\u524d“\u672a\u68c0\u7d22\u5230\u7b5b\u9009/\u914d\u5bf9\u8282\u70b9”，\u8fd8\u4e0d\u80fd\u65ad\u8a00“\u77e5\u8bc6\u5e93\u4e00\u5b9a\u6ca1\u6709”。\u5e94\u5148\u533a\u5206\u53ec\u56de\u4e0d\u8db3\u548c\u77e5\u8bc6\u5e93\u7f3a\u53e3，\u518d\u51b3\u5b9a\u662f\u5426\u6269\u56fe。\n\n\u5c55\u793a\u89c1 [\u6d4f\u89c8\u5668\u7248](index.html)；\u4ee3\u7801\u8fd0\u884c\u548c\u5b8c\u6574\u8bb0\u5f55\u89c1 [\u6280\u672f\u4e0e\u590d\u73b0\u8bf4\u660e](\u6280\u672f\u4e0e\u590d\u73b0\u8bf4\u660e.md)。\n'
